    s=read(PUB/'summary.json');a=read(PUB/'acceptance.json');cal=read(PUB/'calibration.json');reg=read(PUB/'regression_summary.json');inner=read(PUB/'inner_metrics.json')['rows'];goal=a['R2_joint_empirical_target'];comparison={(r['table'],r['half'],r['seed'],r['contrast']):r for r in s['paired_comparisons']};text=[]
