    primary=[r for r in s['rows'] if r.get('policy')=='R2'];noop=sum(r['action_statistics_full_task']['accepted_actions']==0 for r in primary);zero_recovery=sum(r['action_statistics_source_role']['accepted_new_JEPA_short16_true_units_recovered']==0 for r in primary);gain=sum(r['segment_f1_50_multi']>s['systems'][r['table']][r['half']][BASE]['segment_f1_50_multi'] for r in primary)
    text[4:4]=[f"Primary behavior: {noop}/24 R2 evaluation cells accept no action; {gain}/24 improve pooled multi segment F1 over Base; {zero_recovery}/24 recover no JEPA-exclusive true short16 unit. These are repeated constructed evaluation cells, not independent patients. Zero harm in a no-edit cell does not establish useful risk discrimination or satisfy the required recovery objective.",'']
